reference_solution:
def closedIsland(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    def flood(r, c):
        st = [(r, c)]
        grid[r][c] = 1
        while st:
            x, y = st.pop()
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nx, ny = x + dx, y + dy
                if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == 0:
                    grid[nx][ny] = 1
                    st.append((nx, ny))
    for i in range(R):
        for j in range(C):
            if (i in (0, R - 1) or j in (0, C - 1)) and grid[i][j] == 0:
                flood(i, j)
    n = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 0:
                n += 1
                flood(i, j)
    return n

