def closedIsland(grid):
    if not grid:
        return 0
    R, C = len(grid), len(grid[0])
    seen = set()
    cnt = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] == 0 and (i, j) not in seen:
                q = [(i, j)]
                seen.add((i, j))
                closed = True
                for x, y in q:
                    if x in (0, R - 1) or y in (0, C - 1):
                        closed = False
                    for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < R and 0 <= ny < C and grid[nx][ny] == 0 and (nx, ny) not in seen:
                            seen.add((nx, ny))
                            q.append((nx, ny))
                cnt += closed
    return cnt

